#include <stdio.h>
int main(void)
{
  int n, i, x, sum = 0;
  double avg;
  scanf("%d", &n);
  for (i = 1; i <= n; i++) {
    scanf("%d", &x);
    sum += x;
  }
  avg = (double)sum / n;
  printf("%.2f\n", avg);
  return 0;
}
